async function main() {
  let criados = 0;
  let atualizados = 0;
  let rotasCriadas = 0;

  for (const it of ITENS) {
    const nomeItem = it.nomeItem.trim().toUpperCase();
    const existente = await prisma.itemEstoque.findUnique({ where: { nomeItem } });

    const item = await prisma.itemEstoque.upsert({
      where: { nomeItem },
      update: {
        descricao: it.descricao,
        endereco: it.endereco,
        quantidade: it.quantidade,
        foto: it.foto,
        ultimoAlteradoPor: "seed",
      },
      create: {
        nomeItem,
        descricao: it.descricao,
        endereco: it.endereco,
        quantidade: it.quantidade,
        foto: it.foto,
        ultimoAlteradoPor: "seed",
      },
    });

    if (existente) atualizados++;
    else criados++;

    // Recria as rotas desse item (evita duplicar se rodar o seed 2x)
    await prisma.rotaItem.deleteMany({ where: { itemId: item.id } });
    for (const rota of it.rotas) {
      await prisma.rotaItem.create({
        data: {
          itemId: item.id,
          destino: rota.destino,
          automatica: rota.automatica,
          observacao: rota.observacao ?? null,
          criadaPor: rota.criadaPor ?? null,
        },
      });
      rotasCriadas++;
    }
  }

  console.log(`Concluído: ${criados} itens criados, ${atualizados} atualizados, ${rotasCriadas} rotas criadas (total ${ITENS.length} itens).`);
}

main()
  .catch((e) => {
    console.error("Erro ao popular itens de teste:", e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
